BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
S=lambda w:'https://www.etymonline.com/word/'+w
O=lambda w:'https://www.oxfordlearnersdictionaries.com/definition/english/'+w
K=lambda w:'https://en.wiktionary.org/wiki/'+w
W=[
E('make','/meɪk/','制作；使成为；促成；获得；品牌〔名词〕','把材料变成一张桌子，是 make a table；让别人笑起来，是 make someone laugh。先抓“让某种东西或结果出现”，就能连接很多常用搭配。','动词继承古英语 macian，经中古英语 maken 到 make；更远的日耳曼语、印欧语分析涉及塑造、配合等，不必把某种史前场景当定论。现代名词“制造方式、品牌”与制作义相接；古旧名词 make“伴侣”另接 gemaca，不混作现代品牌义的直接祖先。',[['古英语 macian → 中古英语 maken','做、塑造、制造；使某种结果出现'],['英语 make 动词及相关名词','制作、使成为等；制造方式、类型或品牌']],'make a decision 是作决定，make money 是挣钱，不必真做出一件实体。make someone happy 用形容词说结果；make someone laugh 用动词说被引出的动作。What make is it? 则问品牌或制造商类型。','make a mistake；make a difference；make someone do；make it〔赶到、做到或成功〕。过去式和分词为 made。','make 常突出产物或结果，do 常说做活动、任务；实际仍要记搭配。主动式 make someone do 不带 to，被动式 be made to do 通常带 to。',('We made a small table from the leftover wood.','我们用剩下的木料做了一张小桌子。'),('Her message made me smile.','她的消息让我笑了起来。'),('What make of camera do you use?','你用什么牌子的相机？'),('If we leave now, we can make the last train.','如果现在出发，我们就能赶上末班火车。'),sources=[S('make'),K('make'),O('make_1')]),
E('made','/meɪd/','制作了；制成的；使……成为了〔make 的过去式、过去分词〕','看到 made，要想到 make 已经发生，或某物已经做成。The table was made… 关注桌子怎样被制作，而 She made… 讲她做了什么。','古英语 macian 的过去式、分词有 macode、macod 等形式，中古英语 maked 等逐渐缩短为 made。现代它是 make 的不规则过去式和分词，不是另加一个新的英语词根。',[['古英语 macian；相关 macode／macod','制作；相应过去式、分词形式'],['中古英语 maked／made → 英语 made','词形缩短后成为 make 的常用过去式、过去分词']],'made of 常指出能认出的主要材料，如木椅；made from 常用于原材料经过明显加工的情形。made by 指制作者。a decision made yesterday 中，made 说明决定是在昨天作出的。','made of wood；made from grapes；made by hand；have it made〔处境优越、成功有保障〕。','made /meɪd/ 与 maid“女佣”同音但不同词。make 的过去式不写 maked；表示被制作时常需要 be made，不能只把 made 当万能的“是”。',('The bowls are made of clay.','这些碗是用黏土制成的。'),('We made the decision after checking the figures.','核对数字后，我们作出了决定。'),sources=[S('made'),K('made'),O('make_1')]),
E('making','/ˈmeɪkɪŋ/','制作、形成的过程；造就；形成中的事物〔也作 make 的 -ing 形式〕','电影成片只有两小时，背后的筹备、拍摄和剪辑却可能持续几年。the making of the film 就把目光转向“它是怎样做出来的”。','古英语已有 macung“制作”，经中古英语 making 到现代名词；现代也按 make 去 e 加 -ing 形成动词形式。名词并非等到现代进行时出现才临时产生。',[['古英语 macian → macung','做、制作；制作过程的名词'],['中古英语 making → 英语 making','制作、形成；也与现代动词 -ing 形式同形']],'in the making 是正在形成中；years in the making 是筹备制作了很多年。the making of someone 还可说某段经历造就了这个人。','the making of a film；in the making；years in the making；the makings of〔具备成为某物的潜质〕。','making 可以讲过程；maker 是做这件事的人或设备。a film in the making 尚在制作，不是已经上映的成片。',('The documentary explores the making of the first album.','这部纪录片讲述了首张专辑的制作过程。'),('The new bridge was ten years in the making.','这座新桥从筹备到建成历时十年。'),sources=[K('making'),O('making')]),
E('maker','英 /ˈmeɪkə/；美 /ˈmeɪkər/','制造者；制作人；制造设备','谁把东西做出来，谁就是 maker；换成一台专门做咖啡的机器，它也可以是 a coffee maker。-er 在这里不只指人。','make 去 e 加 -er，中古英语已有 maker／makere。早期可说创造者，后来广用于制造商、工匠及执行制作功能的器具。',[['英语 make；-er','制作；做事的人或器具'],['中古英语 maker／makere → 英语 maker','制造者、创作者；后来也说设备']],'car makers 是汽车制造商；a maker of violins 是制琴师。现代 maker 社群常指喜欢亲手设计、制作、改装东西的人。大写 the Maker 在宗教语境可指造物主。','a furniture maker；a coffee maker；the maker of a product；maker culture。','maker 范围比 manufacturer 宽，个人手作、机器都能用；manufacturer 通常说生产商品的企业或生产者。',('The maker’s name is engraved on the back of the watch.','制表者的名字刻在手表背面。'),('Our old coffee maker still works perfectly.','我们的旧咖啡机仍然运转良好。'),sources=[S('maker'),K('maker'),O('maker')]),
E('remake','动词 /ˌriːˈmeɪk/；名词 /ˈriːmeɪk/','重新制作；改造；重拍版、重制版','同一个故事重新拍，或把旧作品按新的技术重新做一遍，就是 remake。它不只是再播放一次原来的成品。','re-“再、重新”加 make，17 世纪已有动词，电影领域后来采用；20 世纪形成常见的电影重拍版名词。现代名词和动词通常重音不同。',[['英语 re-；make','重新；制作'],['英语 remake 动词 → 电影等领域的名词','重新制作；后来指重新制作的版本']],'remake a film 是重拍，a remake of a classic 是经典作品的新版。用于机构或人的生活时，remake 也能说彻底重塑。','remake a film；a remake of；be remade；remake one’s life。','remake 重新制作；sequel 是续集，通常接着讲后来的故事。重新上映原片不是自动变成 remake。',('The studio plans to remake the film with a new cast.','制片公司计划启用新演员阵容重拍这部电影。'),('The remake keeps the original story but changes the setting.','重拍版保留了原来的故事，但改变了背景。'),sources=[S('remake'),K('remake'),O('remake_1'),O('remake_2')]),
E('makeup','/ˈmeɪkʌp/','化妆品；妆容；组成、构成','一张脸怎样被修饰出来，可以说 makeup；一个团队由哪些人组成，也可以说 its makeup。两种意思都与“组合成某种样子”相连。','来自英语短语 make up“组成、准备”等。19 世纪名词先有构成方式等义；演员为角色作装扮的用法，又发展出妆容和化妆品义。也见 make-up 拼写，此处统一收连写词头。',[['英语 make；up','制作、形成；组合完成的相关作用'],['短语 make up → 名词 makeup／make-up','组成方式；戏剧装扮后发展出妆容、化妆品义']],'wear makeup 是化妆，remove makeup 是卸妆。the makeup of a team 说团队组成，不是问每个人有没有抹粉。美国英语 a makeup exam 还可指补考，用来补上错过的考试。','put on makeup；remove makeup；genetic makeup；the makeup of a group。','名词 makeup 与分写的动词 make up 不完全等同。make up a story 是编故事，make up after an argument 是和好，不能把这些都当作化妆。',('She removed her makeup before going to bed.','她睡前卸了妆。'),('The survey examines the age makeup of the neighbourhood.','这项调查研究了这个社区的年龄构成。'),sources=[S('make-up'),K('makeup'),'https://www.merriam-webster.com/dictionary/makeup']),
E('makeover','英 /ˈmeɪkəʊvə/；美 /ˈmeɪkoʊvər/','外观改造；形象焕新','原来的房间还在，但配色、家具和灯光都重新搭配；原来的那个人还在，但发型、穿着和妆容有了新样子。这种变化就是 makeover。','名词来自短语 make over“重新塑造、改造”。make 与表示重新的 over 先组成动词短语，后来形成指改造及其结果的名词，现代尤其常说外观改变。',[['英语 make；over〔重新的相关副词义〕','制作；重新'],['动词短语 make over → 名词 makeover','重新改造；人的形象或场所外观焕新']],'give a room a makeover 是给房间换个面貌；a makeover show 常展示人物或住宅改造。它重点在整体呈现，不保证内部功能也进行了同样深度的改变。','give something a makeover；a complete makeover；a kitchen makeover。','makeup 通常说妆容或化妆品；makeover 是较整体的形象改造。remake 则强调重新制作一个作品或东西。',('The waiting room received a makeover with brighter colours and new chairs.','候诊室换了更明亮的配色和新椅子，面貌焕然一新。'),('She asked for a simple makeover that suited her everyday style.','她想做一次符合日常风格的简单形象改造。'),sources=[S('makeover'),O('makeover'),K('makeover')]),
E('makeshift','/ˈmeɪkʃɪft/','临时凑合的；应急搭成的','没有正式桌子，就把一块木板架在两个箱子上先用。这张桌子是 makeshift：先用现有东西顶上，解决眼前需要。','make 与 shift 的旧名词义“办法、权宜之计”组合。早期还有指善用手段之人的旧名词义，后来形成临时应急的形容词和替代物名词；不是“制造轮班”。',[['英语 make；shift〔办法、权宜之计〕','设法做出；应付眼前需要的办法'],['早期 makeshift 的人称旧义；后来的形容词、物件名词','善用手段的人等旧用法 → 临时应急的、临时代用品']],'a makeshift shelter 是临时搭的遮蔽处；a makeshift desk 是用其他东西凑成的桌子。它暗示不是专为长久用途设计，但不必然表示完全不能用。','a makeshift shelter；a makeshift desk；makeshift arrangements。','temporary 只说明使用时间短；makeshift 还常说明利用手头材料、临时拼凑。正式租来的临时办公室不一定是 makeshift。',('We used two boxes and a board as a makeshift table.','我们用两个箱子和一块木板凑成了一张临时桌子。'),('The hikers rested under a makeshift shelter while the rain passed.','徒步者在临时搭起的遮蔽处休息，等雨过去。'),sources=[S('makeshift'),K('makeshift'),O('makeshift')]),
E('lawmaking','英 /ˈlɔːmeɪkɪŋ/；美 /ˈlɔːmeɪkɪŋ/','立法；制定法律的过程','一项规则要变成法律，往往要经过提出、讨论、修改和表决。lawmaking 把这类形成法律的工作整体说出来。','英语 law 与 making 组合；making 是 make 的制作、形成过程名词。law 的历史经古英语接北欧语法律词，但整个 lawmaking 是英语内部组合。',[['英语 law；making〔make 的名词形式〕','法律；制定、形成的过程'],['英语 lawmaking','制定法律的活动与过程']],'lawmaking process 是立法过程；lawmaking powers 是制定法律的权力。它关注形成法律，与日后执行法律不是同一项工作。','the lawmaking process；lawmaking powers；a lawmaking body。','lawmaking 是活动，lawmaker 是参与立法的人。law enforcement 是执法，不能只因都与法律有关就混用。',('The class discussed the main stages of lawmaking.','课堂讨论了立法的主要阶段。'),('Public hearings can be part of the lawmaking process.','公开听证可以是立法过程的一部分。'),sources=[K('lawmaking'),'https://www.merriam-webster.com/dictionary/lawmaking']),
E('lawmaker','英 /ˈlɔːmeɪkə/；美 /ˈlɔːmeɪkər/','立法者；议员〔新闻常用〕','新闻里说 lawmakers debated the proposal，通常就是议员们在讨论提案。maker 在这里是参与制定规则的人，不是用手制造某件物品。','law 加 maker；英语晚期中古时期已有这个组合。它与 lawmaking 共享构件，但不必把现代名词画成先由 lawmaking 再删去后缀而来。',[['英语 law；maker','法律；制定者'],['英语 lawmaker〔15 世纪已有记录〕','制定法律的人；常用于立法机关成员']],'新闻常用 lawmakers 概称参与立法的议员，不逐一写他们的正式职衔。具体制度中的权限和身份仍取决于文章所在国家与机构。','lawmakers debated；a group of lawmakers；local lawmakers。','lawmaker 是立法者；lawyer 是律师。会研究或使用法律，不等于拥有制定法律的职位。',('Lawmakers debated the proposal late into the evening.','议员们讨论这项提案，一直持续到晚上很晚。'),('Several lawmakers asked for clearer wording in the bill.','几位议员要求把法案的措辞写得更清楚。'),sources=[S('lawmaker'),K('lawmaker'),O('lawmaker')]),
E('filmmaker','英 /ˈfɪlmmeɪkə/；美 /ˈfɪlmmeɪkər/','电影创作者；电影制作人','把画面、声音和故事组织成一部电影的人，可以称 filmmaker。这个称呼强调创作电影，不一定只对应片尾某一个职位。','film 与 maker 在英语中组合。19 世纪同形组合还曾用于与摄影胶片制作相关的人或物；20 世纪初明确用于电影创作者。现代拍数字电影的人同样可以叫 filmmaker。',[['英语 film；maker','薄膜、胶片，后来也指电影；制作人或物'],['较早胶片制作相关组合 → 电影创作义 filmmaker','随 film 的电影义发展，成为电影创作者称呼']],'独立电影报道常用 independent filmmaker；documentary filmmaker 是纪录片创作者。一个人可能同时编剧、导演、拍摄，因此这个词比单一工种名称更宽。','an independent filmmaker；a documentary filmmaker；young filmmakers。','director 是导演这一具体职位，filmmaker 更宽泛；不是所有 filmmakers 都只负责导演，也不表示制造塑料胶片的工人。',('The filmmaker spent two years following the same family.','这位电影创作者花了两年时间跟拍同一个家庭。'),('The festival gives young filmmakers a place to show their work.','这个电影节为年轻电影人提供了展示作品的平台。'),sources=[S('film-maker'),K('filmmaker'),O('film-maker')]),
E('shoemaker','英 /ˈʃuːmeɪkə/；美 /ˈʃuːmeɪkər/','鞋匠；制鞋者','量脚、裁皮、缝合鞋面，把材料做成一双鞋的人，就是 shoemaker。词里的 maker 对应实实在在的制作。','shoe 与 maker 组合，中古英语已有相关词形。更早古英语用过其他“鞋＋工匠”词，但现代 shoemaker 是这一组合自身的历史，不需要把那些旧词硬串成同一祖先链。',[['英语 shoe；maker','鞋；制作的人'],['中古英语 shoemaker 类组合 → 英语 shoemaker','制鞋者、鞋匠']],'可以指传统手工制鞋匠，也可泛指制鞋企业或生产者。上下文会说明说的是具体工匠还是品牌。','a skilled shoemaker；a traditional shoemaker；a local shoemaker。','cobbler 常侧重修鞋，shoemaker 首先说制作鞋；实际店铺和日常称呼有重叠，不用把两种工作绝对隔开。',('The shoemaker measured both feet before cutting the leather.','鞋匠裁皮前量了双脚。'),('A local shoemaker crafted the boots by hand.','当地一位鞋匠手工制作了这双靴子。'),sources=[S('shoemaker'),K('shoemaker'),O('shoemaker')]),
E('homemaker','英 /ˈhəʊmmeɪkə/；美 /ˈhoʊmmeɪkər/','料理家务、照顾家庭的人','把房子维持成能让一家人生活的家，需要安排饮食、清洁、照护和日常事务。以这些家庭工作为主要职责的人，可以称 homemaker。','home 加 maker，19 世纪已有多个“营造、经营家园”的用法，后来常指主要负责家务和家庭照护的人。这里的 make a home 说经营家庭生活，不是施工盖房。',[['英语 home；maker','家、家庭生活；营造者'],['19 世纪 homemaker 的多种家庭相关用法 → 现代常用义','营造家园；主要负责家务和家庭生活的人']],'这个词不限定性别，也不要求已经结婚。常见于个人背景介绍或职业状况说明，强调所承担的家庭工作。','a full-time homemaker；work as a homemaker；a parent and homemaker。','homemaker 不是 housebuilder“建房者”；也不同于受雇替另一家庭管理家务的 housekeeper。实际职责可能部分相似，身份关系不同。',('After the move, he became the family’s main homemaker.','搬家后，他成为家里主要料理家务的人。'),('Her years as a homemaker taught her to organize many tasks at once.','多年料理家务的经历让她学会同时安排多项事务。'),sources=[S('homemaker'),K('homemaker'),O('homemaker')]),
E('moneymaker','英 /ˈmʌnimeɪkə/；美 /ˈmʌnimeɪkər/','赚钱的人或事物；盈利项目','店里有款产品长期卖得好、带来利润，老板可能说它是 a moneymaker。重点是能赚钱，不是产品里真的会吐出纸币。','money 与 maker 组合，早期也指铸造钱币的人。后来“make money 挣钱”的常用表达推动它用于善于赚钱的人、盈利商品或项目。',[['英语 money；maker','钱；制造或促成的人、物'],['较早 moneymaker：铸币者；后来挣钱者、盈利之物','从制作钱币的旧义扩展到获得收益的现代用法']],'a reliable moneymaker 是稳定带来收益的项目；a potential moneymaker 是被认为有赚钱潜力的东西。口语和商业报道较常见。','a big moneymaker；a reliable moneymaker；a potential moneymaker。','moneymaker 描述赚钱能力，不自动保证投入、风险或质量如何。它通常不是指银行、提款机或印钞机器。',('The small café became a steady moneymaker for the family.','这家小咖啡馆成了家庭稳定的收入来源。'),('The sequel was a bigger moneymaker than the original film.','续集比原版电影更赚钱。'),sources=[S('money-maker'),K('moneymaker'),'https://www.merriam-webster.com/dictionary/moneymaker']),
E('pacemaker','英 /ˈpeɪsmeɪkə/；美 /ˈpeɪsmeɪkər/','领跑者；心脏起搏点或起搏器','比赛中有人先按目标速度跑，让后面的选手跟上节奏；心脏中也需要产生节律的信号。pacemaker 把两者都抓在“定节奏”这个点上。','pace“步速、节奏”加 maker，19 世纪先用于带领速度的人或物；20 世纪用于心脏的自然节律来源，再用于人工心脏起搏器。pace 不是 peace“和平”。',[['英语 pace；maker','速度、节奏；设定或促成者'],['英语 pacemaker：比赛、训练中带节奏者','19 世纪已有'],['自然心脏起搏点；后来人工起搏器','20 世纪将“定节奏”用于生理结构及电刺激装置']],'日常医疗语境的 a pacemaker 常指用电脉冲帮助调节心跳的装置；natural pacemaker 则可说心脏自然产生节律的组织。体育语境依旧是领跑、领速的人。','a race pacemaker；an artificial pacemaker；the heart’s natural pacemaker。','pacemaker 的核心是节奏，不是直接替代整个心脏泵血。peacemaker 多一个 e，意思是调解冲突、促成和平的人。',('The pacemaker kept a steady pace for the first few laps.','领跑者在前几圈保持了稳定速度。'),('The diagram shows how a pacemaker sends electrical pulses to the heart.','图中展示了起搏器如何向心脏发送电脉冲。'),sources=[S('pacemaker'),K('pacemaker'),O('pacemaker'),'https://www.nhlbi.nih.gov/health/pacemakers']),
E('match','/mætʃ/','相配的人或物；比赛；匹配、比得上；火柴〔另源〕','两只袜子能配成一双，两支队伍能组成一场比赛，信息能对得上，都属于“配对、对应”这一支。用来点火的 match 则是另一个恰好同拼写的词。','配对义来自古英语 mæcca／gemæcca“伙伴、配偶、一对中的一个”，经中古英语 macche；动词由这一名词发展。它与 make 的早期日耳曼语材料有联系，却不是现代 make 改几个字母直接生成。火柴义来自古法语 meiche“灯芯”，更远可能接拉丁／希腊 myxa，具体传承仍有不确定处。',[['两条来源并列：古英语 mæcca／gemæcca；古法语 meiche','伙伴、相配者；灯芯'],['中古英语各支 macche 等同形形式','配对义承接日耳曼语；引火物义借自法语'],['英语 match','相配者、比赛及匹配动词；另一支发展为现代火柴']],'a good match 可说合适的伴侣或搭配；a football match 是两方较量；the details match 是细节一致。strike a match 才是划火柴。不能把比赛解释成点燃火焰。','match the description；match A with B；be a good match；win a match；strike a match。','match 既可表示相似对应，也可表示实力相当；不要求任何场景都完全一样。火柴这一支与“般配”分源，只有拼写与读音相同。',('The paint is a good match for the colour of the door.','这款油漆与门的颜色很相配。'),('The two teams played an exciting match.','两支球队打了一场精彩的比赛。'),('The number on the ticket matches the number in the email.','票上的号码与邮件里的号码一致。'),('She struck a match to light the candle.','她划着一根火柴点燃蜡烛。'),sources=[S('match'),K('match'),O('match_1'),O('match_2')]),
E('matchless','/ˈmætʃləs/','无可匹敌的；无与伦比的','到处找，也找不到能与它并肩相比的对象，就是 matchless。这里的 match 是匹敌者，不是火柴。','match“同等者、匹敌者”加 -less；16 世纪已有。历史上也受到中古英语 makeless“无匹者”的影响或部分承接，那里旧名词 make 是伙伴、相配者，与现代 make“制作”不能简单等同。',[['英语 match〔匹敌者〕；旧名词 make〔伴侣、相配者〕及 makeless','没有能匹敌的对象；旧的同类表达'],['英语 match + -less → matchless','无可匹敌的；受到早期 makeless 一类形式的联系或影响']],'常用于赞美技艺、经验、美景，语气比 very good 更强、更有书面或宣传色彩。matchless skill 是赞其技艺无人能比，并非真的做过完整排名统计。','matchless skill；matchless beauty；matchless experience。','matchless 是没有能相比的对象；mismatched 是配得不合适。前者通常赞美，后者指出组合出了问题。',('The review praised the musician’s matchless control of tone.','评论赞扬了这位音乐家无可匹敌的音色控制能力。'),('From the summit, we had a matchless view of the valley.','从山顶望去，我们看到了无与伦比的山谷景色。'),sources=[S('matchless'),K('matchless'),O('matchless')]),
E('matchmaker','英 /ˈmætʃmeɪkə/；美 /ˈmætʃmeɪkər/','媒人；牵线搭桥者；配对安排者','把两个可能合得来的人介绍认识，希望他们成为伴侣，就是在做 matchmaker。现代也能把这种牵线用于工作或商业合作。','match“配对、婚配”加 maker；17 世纪已有婚姻牵线者的用法。match 与 maker 是并列构词材料，不是由一个词一路变出另一个。',[['英语 match；maker','合适的配对、婚配；促成者'],['英语 matchmaker','促成婚配的人；后来也用于安排其他相配关系者']],'play matchmaker 是充当红娘；商业文章也会说 someone acts as a matchmaker between investors and companies。这里的 match 选的是合适关系，不是火柴义。','play matchmaker；a professional matchmaker；act as a matchmaker。','matchmaker 是安排配对的人；partner 是配对关系中的一方。maker 不只说生产实体，也能说促成关系。',('Her friends kept trying to play matchmaker.','她的朋友们总想给她牵线介绍对象。'),('The event acted as a matchmaker between small firms and potential partners.','这场活动为小企业和潜在合作伙伴牵线搭桥。'),sources=[S('matchmaker'),K('matchmaker'),O('matchmaker')]),
E('matchmaking','/ˈmætʃmeɪkɪŋ/','牵线婚配；安排匹配的活动或过程','有人负责把合适的两方联系起来，这个过程就是 matchmaking。婚恋中配伴侣，游戏中配对手，商务活动中配合作方，具体标准随场景改变。','英语 match“配对”与 making“促成、制作过程”组合，与 matchmaker 这一职业名同属一个构词系列。不是把现代名词 matchmaker 机械删去 -er 就能解释全部历史。',[['英语 match；making','相配关系；促成的过程'],['英语 matchmaking','安排婚配；后来泛用于安排合适双方的过程']],'传统用法说替人介绍伴侣；online matchmaking 可以是婚恋服务，也可以在游戏语境指配对玩家。先看配的是谁，别一见这个词就译成结婚。','a matchmaking service；online matchmaking；business matchmaking；a matchmaking system。','matching 可以泛说匹配、相符；matchmaking 更突出组织安排，让原本未联系的双方形成一组。配对成功不保证彼此一定满意。',('The family’s matchmaking efforts made her laugh.','家人们忙着替她牵线，让她觉得好笑。'),('The game’s matchmaking system groups players with similar skill levels.','游戏的匹配系统把水平相近的玩家分到一起。'),sources=[K('matchmaking'),O('matchmaking'),'https://www.merriam-webster.com/dictionary/matchmaking']),
]
names=[w['word'] for w in W]+['troublemaker','peacemaker','makerspace']
cat=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text()) if x['id']=='B2894')
EX={w:'按用户要求略过带连字符的词条。' for w in cat['family'] if '-' in w}
EX['makepeace']='作调解者的古旧词，本轮复用更常用的 peacemaker，不另展开。'
ROOT=dict(id='B2894',meaning='做、制作；使某种结果出现',core='make 不只说把材料做成东西，也说让结果出现：做蛋糕、作决定、让别人笑、促成和平。maker 就是做这件事的人或设备。',image='macian 做、塑造 → make → 制作过程 making、制作者 maker，以及不同结果的组合词。',intro='先理解 make 的结果感，再看组合词具体促成了什么。match／matchless 另放在历史相关支线：配对词与 make 的早期材料有关，火柴义却来自另一条法语路线。',forms='make 继承古英语 macian，made 来自旧过去式、分词形式的缩短；making 的名词已有古英语 macung。makeup、makeover 来自短语固定成的名词。matchless 还联系旧名词 make“伴侣”的 makeless，不能说它就是现代制作动词的普通派生。',branches=[['制作与结果的基础','make, made, making, maker'],['重新制作与临时改造','remake, makeup, makeover, makeshift'],['制定规则和创作产品','lawmaking, lawmaker, filmmaker, shoemaker'],['经营生活、收益与节奏','homemaker, moneymaker, pacemaker'],['促成局面与共同制作','troublemaker, peacemaker, makerspace'],['历史相关的配对支线','match, matchless, matchmaker, matchmaking']],contrasts='pacemaker 定节奏，peacemaker 促和平；makeup 是妆容或构成，makeover 是整体形象改造。match 的配对义与火柴义分源，不能因为同形就讲成同一条现代演化。',practice='给 make、maker、making 各写一句，再用 pacemaker 与 peacemaker 说明少一个字母为何改变了整个意思。',words=names,exclude=EX)
if __name__=='__main__':
 for kind,data in [('roots',[ROOT]),('words',W)]: (OUT/(kind+'_batch200_vid_255.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print('make:',len(W),'new;',sum(len(w['examples']) for w in W),'examples')
